/* 布局·一屏尽览 —— 全站压缩进一屏（密度实验） */
body.l-one-screen { font-size: 14px; }
body.l-one-screen .hero { min-height: auto; padding-top: 130px; padding-bottom: 24px; gap: 32px; }
body.l-one-screen .hero h1 { font-size: clamp(36px, 5vw, 52px); }
body.l-one-screen .hero-desc { margin-bottom: 18px; }
body.l-one-screen .hero-stats { margin-top: 26px; gap: 26px; }
body.l-one-screen .avatar-wrap { width: min(140px, 30vw); }
body.l-one-screen section { padding-top: 40px; padding-bottom: 8px; }
body.l-one-screen .section-desc, body.l-one-screen .skills-note { display: none; }
body.l-one-screen .section-title { font-size: 24px; margin-bottom: 4px; }
body.l-one-screen .section-tag { margin-bottom: 8px; padding: 2px 10px; font-size: 11.5px; }
body.l-one-screen .projects-grid { grid-template-columns: repeat(3, 1fr); gap: 12px; }
body.l-one-screen .card { padding: 16px; gap: 8px; }
body.l-one-screen .card .desc { display: none; }
body.l-one-screen .card.featured .desc { display: block; font-size: 13px; }
body.l-one-screen .skills-wrap { gap: 26px; }
body.l-one-screen .bar-row { margin-bottom: 10px; }
body.l-one-screen .tag-block { margin-bottom: 12px; }
body.l-one-screen .about-wrap { gap: 26px; }
body.l-one-screen .about-text p:nth-of-type(n+3) { display: none; }
body.l-one-screen .about-text p { margin-bottom: 10px; }
body.l-one-screen .fact { padding: 10px 14px; }
body.l-one-screen .post { padding: 14px 18px; }
body.l-one-screen .post-body p { display: none; }
body.l-one-screen .post:nth-of-type(3) { display: none; }
body.l-one-screen .contact-card { padding: 16px; }
body.l-one-screen footer { margin-top: 20px; padding-bottom: 20px; }
@media (max-width: 720px) {
  body.l-one-screen .projects-grid { grid-template-columns: 1fr 1fr; }
}
